/**
 * Advanced evaluation scenarios, ported from an internal `llm-bench` test plan.
 *
 * The original plan is a Python framework layered on evalscope. Everything in
 * this file — scenario catalogue, load profiles, pass/fail thresholds, error
 * taxonomy and the quality benchmark suites — is the plan's *configuration and
 * evaluation contract* expressed as native types so the desktop tool can run
 * the scenarios without a Python runtime.
 *
 * Metric definitions deliberately match the plan's metric table so numbers
 * produced here are comparable with reports generated by the Python CLI:
 *   TTFT        request sent -> first token
 *   E2E         request sent -> last token
 *   TPOT        mean time per output token
 *   ITL / ITPL  latency between adjacent tokens
 *   Decode TPS  (N-1) / (E2E - TTFT)
 *   Prefill TPS input tokens / TTFT (approximation, includes scheduling)
 */

import type { OllamaEnvironment } from "./types";

