/* -------------------------------------------------------------------------- */
/* Load profile defaults (plan section 5 & 9)                                  */
/* -------------------------------------------------------------------------- */

export type LatencyCombo = { inputTokens: number; outputTokens: number };

/** Plan scenario A default input×output matrix. */
export const DEFAULT_LATENCY_COMBOS: readonly LatencyCombo[] = [
  { inputTokens: 128, outputTokens: 128 },
  { inputTokens: 512, outputTokens: 256 },
  { inputTokens: 1_024, outputTokens: 256 },
  { inputTokens: 1_024, outputTokens: 512 },
  { inputTokens: 2_048, outputTokens: 512 },
] as const;

/** Plan scenario B stepped concurrency ladder. */
export const DEFAULT_CONCURRENCY_LEVELS = [1, 2, 4, 8, 16, 32] as const;

/** Plan scenario C context ladder (1K -> 128K). */
export const DEFAULT_CONTEXT_LEVELS = [
  1_024, 2_048, 4_096, 8_192, 16_384, 32_768, 65_536, 131_072,
] as const;

/** Plan needle-in-haystack length ladder. */
export const DEFAULT_NEEDLE_LENGTHS = [4_096, 16_384, 65_536] as const;

/** Canonical load profile: fixed 1024 input + 512 output (plan decision record). */
export const DEFAULT_LOAD_PROFILE = { inputTokens: 1_024, outputTokens: 512 } as const;

/* -------------------------------------------------------------------------- */
/* Judge thresholds (plan section 6.1)                                         */
/* -------------------------------------------------------------------------- */

/**
 * Dual-threshold pass criteria replacing evalscope's hard-coded `check_sla`.
 * A concurrency level passes only when both hold.
 */
export const JUDGE_DEFAULTS = {
  /** Minimum success rate in percent. */
  minSuccessRatePercent: 99,
  /** P95 E2E must stay within baseline (parallel=1) × this multiplier. */
  p95LatencyMultiplier: 1.5,
} as const;

/** Drift thresholds for the stability scenario verdict. */
export const DRIFT_THRESHOLDS = { minorPercent: 10, degradedPercent: 20 } as const;

/** Fairness thresholds (CV = stddev/mean; starvation = latency > median × 5). */
export const FAIRNESS_THRESHOLDS = { warnCv: 0.3, unfairCv: 0.5, starvationMultiplier: 5 } as const;

