/* -------------------------------------------------------------------------- */
/* Run configuration                                                           */
/* -------------------------------------------------------------------------- */

export type LatencyScenarioConfig = {
  combos: LatencyCombo[];
  repeat: number;
  warmup: number;
};

export type ConcurrencyScenarioConfig = {
  levels: number[];
  inputTokens: number;
  outputTokens: number;
  /** Requests per level; the effective count is max(this, level × 4) as in the plan. */
  requestsPerLevel: number;
  /** Probe window per level in milliseconds. */
  probeDurationMs: number;
  /** Steady re-measurement window applied to the confirmed level. */
  steadyDurationMs: number;
  warmup: number;
  temperature: number;
  /** Enable stepped-probe + binary-search refinement (plan scenario B). */
  autotune: boolean;
  /** Upper bound for the autotune ladder. */
  maxConcurrency: number;
};

export type MaxContextScenarioConfig = {
  levels: number[];
  maxOutputTokens: number;
  concurrency: number;
  requestTimeoutMs: number;
};

export type StabilityScenarioConfig = {
  concurrency: number;
  durationMinutes: number;
  inputTokens: number;
  outputTokens: number;
  bucketSeconds: number;
  temperature: number;
};

export type NeedleScenarioConfig = {
  lengths: number[];
  repeats: number;
  maxOutputTokens: number;
  /** Insertion depths as percentages of the haystack. */
  depthPercents: number[];
};

export type AdvancedRunConfig = {
  model: string;
  scenarios: AdvancedScenario[];
  latency: LatencyScenarioConfig;
  concurrency: ConcurrencyScenarioConfig;
  maxContext: MaxContextScenarioConfig;
  stability: StabilityScenarioConfig;
  needle: NeedleScenarioConfig;
  /** Default per-request timeout; scenarios may raise it for long contexts. */
  requestTimeoutMs: number;
  /** Deterministic seed for reproducible prompt filling. */
  seed: number;
};

export function createDefaultAdvancedConfig(model: string): AdvancedRunConfig {
  return {
    model,
    scenarios: ["latency", "concurrency", "fairness"],
    latency: { combos: DEFAULT_LATENCY_COMBOS.map((combo) => ({ ...combo })), repeat: 5, warmup: 1 },
    concurrency: {
      levels: [...DEFAULT_CONCURRENCY_LEVELS],
      inputTokens: DEFAULT_LOAD_PROFILE.inputTokens,
      outputTokens: DEFAULT_LOAD_PROFILE.outputTokens,
      requestsPerLevel: 8,
      probeDurationMs: 15_000,
      steadyDurationMs: 60_000,
      warmup: 1,
      temperature: 0.7,
      autotune: true,
      maxConcurrency: 256,
    },
    maxContext: {
      levels: [...DEFAULT_CONTEXT_LEVELS],
      maxOutputTokens: 16,
      concurrency: 4,
      requestTimeoutMs: 120_000,
    },
    stability: {
      concurrency: 8,
      durationMinutes: 10,
      inputTokens: DEFAULT_LOAD_PROFILE.inputTokens,
      outputTokens: 256,
      bucketSeconds: 60,
      temperature: 0.7,
    },
    needle: {
      lengths: [...DEFAULT_NEEDLE_LENGTHS],
      repeats: 2,
      maxOutputTokens: 64,
      depthPercents: [50],
    },
    requestTimeoutMs: 120_000,
    seed: 42,
  };
}

/* -------------------------------------------------------------------------- */
/* Per-request measurement                                                     */
/* -------------------------------------------------------------------------- */

export type ScenarioRequestOutcome = {
  ok: boolean;
  /** Wall-clock offset (ms) from the scenario start; used for time bucketing. */
  startOffsetMs: number;
  ttftMs?: number;
  e2eMs?: number;
  inputTokens?: number;
  outputTokens?: number;
  /** Latency between adjacent streamed tokens, in milliseconds. */
  interTokenLatenciesMs: number[];
  finishReason?: string;
  responseText: string;
  errorKind?: ScenarioErrorKind;
  errorMessage?: string;
};

