/* -------------------------------------------------------------------------- */
/* Quality benchmark suites (plan `llm_bench/quality/suites.py`)                */
/* -------------------------------------------------------------------------- */

export type QualityBenchCategory = "cn" | "hallucination" | "domain";

export type QualityBenchSpec = {
  /** evalscope dataset name. */
  name: string;
  category: QualityBenchCategory;
  /** Sampling size; 0 means the full set. */
  limit: number;
  /** Generation-mode benchmarks that require a judge model. */
  needJudge: boolean;
  description: string;
};

export const QUALITY_BENCH_CATEGORY_LABELS: Record<QualityBenchCategory, string> = {
  cn: "中文综合",
  hallucination: "幻觉",
  domain: "领域探测",
};

/** The plan's standard 8-benchmark package (~3k sampled questions). */
export const QUALITY_STANDARD_SUITE: readonly QualityBenchSpec[] = [
  { name: "ceval", category: "cn", limit: 0, needJudge: false, description: "52 学科中文综合（val 集）" },
  { name: "cmmlu", category: "cn", limit: 500, needJudge: false, description: "中文特色知识" },
  { name: "truthful_qa", category: "hallucination", limit: 0, needJudge: false, description: "事实性（MC 模式，无需 judge）" },
  { name: "simple_qa", category: "hallucination", limit: 500, needJudge: true, description: "短事实问答（需 judge）" },
  { name: "mmlu_pro", category: "domain", limit: 500, needJudge: false, description: "分学科强弱" },
  { name: "gpqa", category: "domain", limit: 0, needJudge: false, description: "科研推理（GPQA-Diamond 全量 198）" },
  { name: "gsm8k", category: "domain", limit: 200, needJudge: false, description: "数学应用题" },
  { name: "humaneval", category: "domain", limit: 0, needJudge: false, description: "代码生成（全量 164）" },
  { name: "ifeval", category: "domain", limit: 200, needJudge: false, description: "指令遵循" },
] as const;

export const QUALITY_SUITE_NAMES = ["standard", "cn", "halluc", "domain", "fast"] as const;
export type QualitySuiteName = (typeof QUALITY_SUITE_NAMES)[number];

const FAST_SUITE_MEMBERS = new Set(["ceval", "truthful_qa", "gsm8k", "humaneval"]);

/**
 * Resolves a named quality suite. Unknown names fall back to `standard`,
 * matching the Python implementation's `SUITES.get(name, STANDARD_SUITE)`.
 */
export function getQualitySuite(name: string): QualityBenchSpec[] {
  switch (name) {
    case "cn":
      return QUALITY_STANDARD_SUITE.filter((spec) => spec.category === "cn").map((spec) => ({ ...spec }));
    case "halluc":
      return QUALITY_STANDARD_SUITE.filter((spec) => spec.category === "hallucination").map((spec) => ({ ...spec }));
    case "domain":
      return QUALITY_STANDARD_SUITE.filter((spec) => spec.category === "domain").map((spec) => ({ ...spec }));
    case "fast":
      return QUALITY_STANDARD_SUITE.filter((spec) => FAST_SUITE_MEMBERS.has(spec.name)).map((spec) => ({ ...spec }));
    case "standard":
    default:
      return QUALITY_STANDARD_SUITE.map((spec) => ({ ...spec }));
  }
}

/**
 * Builds the `evalscope` bridge command for a suite. Dataset-driven benchmarks
 * need modelscope datasets that are deliberately not bundled with the desktop
 * app, so the tool surfaces a ready-to-run command instead of executing it.
 */
export function buildQualityBridgeCommand(options: {
  suite: string;
  baseUrl: string;
  model: string;
  apiKey?: string;
  parallel?: number;
}): string {
  const parts = [
    "python -m llm_bench quality",
    `-b ${options.baseUrl}`,
    `-m ${options.model}`,
    `-k "${options.apiKey ?? ""}"`,
    `--suite ${options.suite}`,
  ];
  if (options.parallel) parts.push(`--parallel ${options.parallel}`);
  return parts.join(" ");
}
